/**
 * 本端测试面用 react-dom 做静态渲染与真实挂载,而端内没有 `@types/react-dom`
 * (补它要动 `pnpm-lock.yaml` 与整棵 node_modules 链接;多会话并发期间不该由一席单点触发)。
 * 不声明的后果不是"少一条报错":TS7016 之后这两个模块的一切调用都落到 implicit any,
 * 传错实参、取不存在的方法都不会有人拦 —— 本文件把这一小片重新变成**被检查的面**。
 *
 * 只声明**实际用到的那一小块**(`renderToStaticMarkup` / `createRoot` + `Root`),
 * 不复制 react-dom 的完整签名:签名抄多了必然与包漂移(§22c 镜像常量同一条教训)。
 *
 * 移除条件(写在这里以免变成永久影子声明):端内一旦装上 `@types/react-dom`,
 * 本文件必须整份删除 —— 两份声明同时存在会让 TS 报重复模块声明,那才是它该被拿掉的信号。
 */

declare module 'react-dom/server' {
  import type { ReactNode } from 'react'
  export function renderToStaticMarkup(node: ReactNode): string
}

declare module 'react-dom/client' {
  import type { ReactNode } from 'react'
  export interface Root {
    render(node: ReactNode): void
    unmount(): void
  }
  export function createRoot(container: unknown, options?: unknown): Root
}
